#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_semio_graph_complete_actual_typed_public_io_limits(){
 use {semio_framework_artifact_reference::ArtifactDialect,semio_framework_os_kernel::io::io_mechanism::io_export_sqlite_snapshot,semio_framework_os_kernel::io::io_mechanism::io_import_sqlite_snapshot};use store::sqlite_snapshot::*;
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("semioGraph complete public file scope").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
 let dialect=ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"graph".into()};let contract:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎛️semantic.json")).unwrap();let public=&contract["publicIo"];
 for case in contract["cases"].as_array().unwrap(){let source=norm_complete_source(case);let domain=SqliteDatabaseLimits{max_rows:case["rows"].as_u64().unwrap()as usize,max_value_bytes:case["valueBytes"].as_u64().unwrap()as usize,max_schema_bytes:contract["schemaBytes"].as_u64().unwrap()as usize,max_tables:10,max_columns:18,..SqliteDatabaseLimits::default()};let expected=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,domain)).unwrap();let public_case=public["cases"].as_array().unwrap().iter().find(|value|value["id"]==case["id"]).unwrap();
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let encoding_name=match encoding{SnapshotEncoding::Binary=>"binary",SnapshotEncoding::Text=>"text"};let limits=SqliteDatabaseLimits{max_rows:public_case["rows"].as_u64().unwrap()as usize,max_value_bytes:public_case["valueBytes"][encoding_name].as_u64().unwrap()as usize,max_schema_bytes:public["schemaBytes"].as_u64().unwrap()as usize,max_tables:11,max_columns:18,..domain};let file=io_export_sqlite_snapshot(&dialect,&source,encoding,limits,&mut |_|true).await.unwrap().value;assert_eq!(&file[..16],b"SQLite format 3\0");assert_eq!(norm_independent_public_file_extent(&file),serde_json::json!({"rows":public_case["rows"],"valueBytes":public_case["valueBytes"][encoding_name],"schemaBytes":public["schemaBytes"],"tableWidths":public["tableWidths"]}));let restored=io_import_sqlite_snapshot::<SemioGraphSnapshot>(&dialect,&file,limits,&mut |_|true).await.unwrap().value;assert_eq!(restored.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
   for short in[SqliteDatabaseLimits{max_rows:limits.max_rows-1,..limits},SqliteDatabaseLimits{max_value_bytes:limits.max_value_bytes-1,..limits},SqliteDatabaseLimits{max_schema_bytes:limits.max_schema_bytes-1,..limits},SqliteDatabaseLimits{max_tables:10,..limits},SqliteDatabaseLimits{max_columns:17,..limits}]{assert!(io_export_sqlite_snapshot(&dialect,&source,encoding,short,&mut |_|true).await.is_err());assert!(io_import_sqlite_snapshot::<SemioGraphSnapshot>(&dialect,&file,short,&mut |_|true).await.is_err());}
  }
 }eprintln!("[DEBUG] semioGraph actual registered typed IO preserved independently complete public files and all five public-file limits");
}



/// 🧾️ Replaces only the first exact hexadecimal coordinate inside the original authored Graph wire.
fn graph_hex_float_body(hex:&str)->String{
 let text=match fixture().encode_sqlite_snapshot_native(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(){store::io::IoPayload::Text(text)=>text,_=>panic!("Graph text owner produced binary")};
 let mut accept=|_|true;let mut native=semio_framework_value::native_decoding::NativeDecodeControl::new(SqliteDatabaseLimits::default().max_allocation_bytes,&mut accept);
 let body=store::semio_format::split_text_preamble_controlled(&text,crate::standards::v1::subsets::graph::schema::snapshot::STDIO_SEMIOGRAPH_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,&mut native).unwrap();
 let mut start=body.find("nodes=[[").unwrap()+"nodes=[[".len();for _ in 0..3{start+=body[start..].find(',').unwrap()+1;}let end=start+body[start..].find(',').unwrap();format!("{}{}{}",&body[..start],hex,&body[end..])
}
/// 🎛️ Calls the actual Graph document producer with the original caller allocation and progress authority.
fn graph_hex_float_decode(body:&str,limits:SqliteDatabaseLimits)->Result<SemioGraphSnapshot,semio_framework_value::ValueError>{
 use semio_framework_value::native_decoding::{NativeDecodeControl,NativeDecodeProgress};
 let mut callback=|_|true;let mut outer=SqliteSnapshotControl::new(&mut callback,limits);
 outer.allocation_stage(SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let mut callback=|event:NativeDecodeProgress|checkpoint(event.completed,event.total);let mut native=NativeDecodeControl::new(remaining,&mut callback);
  let result=crate::standards::v1::subsets::graph::io::sqlite::snapshot::native_decoding::document(body,&mut native,limits);(result,native.owned_bytes())
 }).unwrap()
}
#[test]
fn sqlite_snapshot_semio_graph_hex_float_original_grammar_and_complete_class_extent(){
 let contract:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎚️hex-float.json")).unwrap();
 for case in contract["valid"].as_array().unwrap(){
  let body=graph_hex_float_body(case["hex"].as_str().unwrap());let value=graph_hex_float_decode(&body,SqliteDatabaseLimits::default()).unwrap();let scalar=value.nodes[0].position.x;let class=if scalar.is_nan(){"nan"}else if scalar.is_infinite(){"infinity"}else{"finite"};assert_eq!(class,case["class"].as_str().unwrap(),"{}",case["id"]);
  let extent=norm_independent_complete_extent(&value);assert_eq!(extent["rows"],19);assert_eq!(extent["valueBytes"],case["graphValueBytes"]);assert_eq!(extent["schemaBytes"],3039);
 }
 for case in contract["invalid"].as_array().unwrap(){assert!(graph_hex_float_decode(&graph_hex_float_body(case["hex"].as_str().unwrap()),SqliteDatabaseLimits::default()).is_err(),"{}",case["id"]);}
 eprintln!("[DEBUG] Semio Graph original hexadecimal f64 grammar matched every independently counted class extent");
}
#[test]
fn sqlite_snapshot_semio_graph_hex_float_complete_cells_precede_original_typed_producer(){
 let contract:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎚️hex-float.json")).unwrap();
 for case in contract["valid"].as_array().unwrap(){
  let body=graph_hex_float_body(case["hex"].as_str().unwrap());let limits=SqliteDatabaseLimits{max_rows:19,max_value_bytes:case["graphValueBytes"].as_u64().unwrap()as usize,max_schema_bytes:3039,max_tables:10,max_columns:18,..SqliteDatabaseLimits::default()};
  graph_hex_float_decode(&body,limits).unwrap();
  assert!(graph_hex_float_decode(&body,SqliteDatabaseLimits{max_value_bytes:limits.max_value_bytes-1,..limits}).is_err(),"complete pretyped coordinate cells {}",case["id"]);
 }
}
